export const ENGINE_PRESETS = [
    {
        presetId: 'default',
        label: 'default',
        description: '迷ったらこれ（静かな広がり）',
        strategyId: 'quiet-spread',
        sourceId: 'keywords',
        channelId: 'discover',
    },
    {
        presetId: 'gentle-rewrite',
        label: 'gentle-rewrite',
        description: '整える（静かなリライト）',
        strategyId: 'quiet-rewrite',
        sourceId: 'rewrite',
        channelId: 'discover',
    },
    {
        presetId: 'seo-push',
        label: 'seo-push',
        description: 'SEO寄り（seo channelで整える）',
        strategyId: 'seo-basic',
        sourceId: 'keywords',
        channelId: 'seo',
    },
    {
        presetId: 'openai-default',
        label: 'openai-default',
        description: 'ChatGPTで生成（topic/title/content）',
        strategyId: 'openai-basic',
        sourceId: 'keywords',
        channelId: 'discover',
    },
];
const presets = new Map();
export const registerPreset = (preset) => {
    presets.set(preset.presetId, preset);
};
export const listPresets = () => [...presets.keys()];
export const getPresetById = (presetId) => {
    if (!presetId)
        return null;
    return presets.get(presetId) ?? ENGINE_PRESETS.find((p) => p.presetId === presetId) ?? null;
};
