import { runContentEngine } from './run.js';
import { resolveEngineConfig } from '../registry/resolve.js';
const hasResolvedConfig = (input) => {
    return 'config' in input;
};
export const runResolvedContentEngine = async (input) => {
    const config = hasResolvedConfig(input)
        ? input.config
        : resolveEngineConfig({
            presetId: input.presetId,
            strategyId: input.strategyId,
            sourceId: input.sourceId,
            channelId: input.channelId,
        });
    const runInput = {
        sourceId: config.sourceId,
        channelId: config.channelId,
        topic: input.topic,
        draft: input.draft,
    };
    const opts = { strategyId: config.strategyId };
    const article = await runContentEngine(runInput, opts);
    return { config, article };
};
